import json

# Load demos for task-47ed202e
with open('/home/USER/runs/paper/qwen-h-in-glm-hpl-u1/frozen/seen-8/play/users/u002/system/state/workspace/programs/task-47ed202e.json') as f:
    demos = json.load(f)

def apply_transformation(grid):
    h, w = len(grid), len(grid[0])
    result = [[0]*w for _ in range(h)]

    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 9:
                run_start = c
                while c < w and grid[r][c] == 9:
                    c += 1
                run_end = c - 1
                run_len = run_end - run_start + 1

                # Check which pixels in this run have 9 below
                run_with_below = []
                for k in range(run_start, run_end + 1):
                    if r + 1 < h and grid[r+1][k] == 9:
                        run_with_below.append(k)

                # Rule: rightmost pixel of length-2 run that has 9 below stays 9; others become 2
                if run_len == 2:
                    if run_with_below:  # At least one pixel has 9 below
                        # Rightmost pixel of the run stays 9
                        result[r][run_start] = 2  # Left
                        result[r][run_end] = 9    # Right
                    else:
                        result[r][run_start] = 2
                        result[r][run_end] = 2
                else:
                    for k in range(run_start, run_end + 1):
                        if r + 1 < h and grid[r+1][k] == 9:
                            result[r][k] = 9
                        else:
                            result[r][k] = 2
            else:
                c += 1

    return result

result = apply_transformation(demos[0]['input'])

